```go
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"reflect"

	"github.com/confluentinc/confluent-kafka-go/kafka"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <your_program> <source_file.go> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	file, err := os.Open(sourceFile)
	if err != nil {
		fmt.Printf("Error opening file: %v\n", err)
		return
	}
	defer file.Close()

	// Parse the source file
	pkg, err := parser.ParsePackage(file.Name())
	if err != nil {
		fmt.Printf("Parse error: %s\n", err.Error())
		return
	}

	// Find the struct declaration
	for _, decl := range pkg.Decls {
		if ast.IsExported(decl) && reflect.TypeOf(decl).Kind() == reflect.Struct {
			structType, _ := reflect.TypeOf(decl).Elem()
			break
		}
	}

	// Check if the struct was found
	if structType == nil {
		fmt.Printf("Struct not found in package.\n")
		return
	}

	// Create a new schema with the given struct type
	schema := kafka.Schema{
		Type: "record",
		Name: structName,
		Fields: map[string]*kafka.Field{
			"field1": {Type: "string"},
			"field2": {Type: "int"},
		},
	}

	f, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		fmt.Printf("Error creating file: %v\n", err)
		return
	}
	defer f.Close()

	err = json.NewEncoder(f).Encode(schema)
	if err != nil {
		fmt.Printf("Error encoding schema: %v\n", err)
		return
	}
	fmt.Printf("Schema written to %s.avsc\n", structName)
}
```

### Explanation:
- **Parsing the Source File**: The `parser` package is used to parse the Go source file into its AST (Abstract Syntax Tree).
- **Finding the Struct Declaration**: The program iterates over the declarations in the parsed package and finds the first occurrence of a struct.
- **Creating the Schema**: An Avro schema is created for the struct using the provided fields (`field1`, `field2`). In this example, we assume these are string and integer types respectively, but you can customize them as needed.

### Usage:
Save the above code to a file called `generate_avro_schema.go`. Then compile and run the program with the following command:

```bash
go run generate_avro_schema.go your_source_file.go struct_name
```

This will create a file named `struct_name.avsc` containing the Avro schema for the struct defined in the source file.

### Notes:
- This script assumes the structure of the generated Avro schema is simple enough to fit within one line of JSON.
- For more complex structs or nested structures, you would need to handle those cases appropriately.
- Make sure you have the necessary packages installed. You can install them using:

```bash
go get github.com/go-playground/validator/v10
```

And then include it in your project by adding `"github.com/go-playground/validator/v10"` to your dependencies list.

