function updateSun() {
  const currentDate = new Date().toLocaleTimeString();
  const currentTime = new Date(currentDate).getHours();

  if (currentTime >= 0 && currentTime < 6) {
    document.getElementById("sun").style.backgroundImage = "url('path/to/sun-yellow.png')";
  } else if (currentTime >= 6 && currentTime < 12) {
    document.getElementById("sun").style.backgroundImage = "url('path/to/sun-bright-yellow.png')";
  } else if (currentTime >= 12 && currentTime < 18) {
    document.getElementById("sun").style.backgroundImage = "url('path/to/sun-orange.png')";
